use std::fs
use std::json
use std::collections::HashMap

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut totals: HashMap<string, float> = HashMap::new()
            let mut names: Vec<string> = []
            for o in orders {
                if !totals.contains_key(o.customer) {
                    totals.insert(o.customer, 0.0)
                    names.push(o.customer)
                }
                let mut sum = totals.get(o.customer).unwrap_or(0.0)
                for it in o.items {
                    sum += (it.qty as float) * it.price
                }
                totals.insert(o.customer, sum)
            }
            names.sort()
            for n in names {
                let t = totals.get(n).unwrap_or(0.0)
                println("${n} ${t:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            std::process::exit(1)
        }
    }
}

